import { policyInsuranceSum, type Item } from "./item-pricing.js";
import { reimbursedShareOf } from "./settlement-clauses.js";

export interface Damage {
  itemType: string;
  amount: number;
}

export interface Incident {
  cause: string;
  damages: Damage[];
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

/** A policy the MHPCO has written: the items it covers and the cap still available. */
export interface Policy {
  items: Item[];
  remainingCap: number;
}

const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;

/** The total the MHPCO will ever pay out on a policy: twice its insurance sum. */
function payoutCapOf(items: Item[]): number {
  return policyInsuranceSum(items) * CAP_MULTIPLE_OF_INSURANCE_SUM;
}

export function openPolicy(items: Item[]): Policy {
  return { items, remainingCap: payoutCapOf(items) };
}

const DEDUCTIBLE_PER_DAMAGE_EVENT = 100;

/** The insured object a damage entry refers to. */
function damagedItemOf(policy: Policy, damage: Damage): Item {
  const insuredItem = policy.items.find((item) => item.type === damage.itemType);
  if (insuredItem === undefined) {
    throw new Error(`The policy does not cover an item of type "${damage.itemType}"`);
  }
  return insuredItem;
}

/**
 * What one damaged item earns its owner: the share the settlement rulebook
 * reimburses, less the deductible the office withholds for each damage event.
 * The office reaches this figure for a damaged object on its own, which is why
 * a second damaged object in the same incident is withheld its own deductible.
 */
function settlementFor(damage: Damage, damagedItem: Item): number {
  return reimbursedShareOf(damage.amount, damagedItem) - DEDUCTIBLE_PER_DAMAGE_EVENT;
}

/**
 * How the MHPCO settles an incident: it looks up the insured object behind each
 * damage entry, settles each one on its own, and pays out what the settlements
 * add up to.
 */
/** Payouts are rounded down, in the MHPCO's favour. */
function roundPayoutInOfficesFavour(payout: number): number {
  return Math.floor(payout);
}

export function claim(policy: Policy, incident: Incident): ClaimResult {
  const payout = incident.damages.reduce(
    (running, damage) => running + settlementFor(damage, damagedItemOf(policy, damage)),
    0,
  );
  const roundedPayout = roundPayoutInOfficesFavour(payout);
  return { payout: roundedPayout, remainingCap: policy.remainingCap - roundedPayout };
}
